/* SDA Kerk: responsive bilingual content and interactive reading tools. */
const $=(s,root=document)=>root.querySelector(s);const $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lang=()=>localStorage.getItem('sdakerk_lang')==='en'?'en':'af';
const L=(af,en)=>lang()==='en'?en:af;
const pages=[['/','Tuis','Home','index'],['/oor-ons','Oor ons','About','about'],['/bybel','Bybel','Bible','bible'],['/studie','Bybelstudie','Study','study'],['/boeke','Boeke','Books','books'],['/videos','Video’s','Videos','videos'],['/gemeentes','Gemeentes','Churches','churches'],['/kontak','Kontak','Contact','contact']];
const social=[['facebook','https://www.facebook.com/AdventisteKerk'],['instagram','https://www.instagram.com/sdakerk/'],['tiktok','https://www.tiktok.com/@sdakerk'],['youtube','https://www.youtube.com/@sdakerk']];
