function socials(){return `<div class="socials">${social.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer" aria-label="${name}"><svg viewBox="0 0 24 24" aria-hidden="true">${socialSvg[name]}</svg></a>`).join('')}</div>`}
function layout(content){const key=document.body.dataset.page;const nav=pages.map(([href,af,en,id])=>`<a href="${href}" ${id===key?'aria-current="page"':''}>${L(af,en)}</a>`).join(''); $('#app').innerHTML=`<header class="site-header"><div class="container header-inner"><a class="brand" href="/" aria-label="SDA Kerk"><img src="/assets/sda-logo.png" alt="SDA Kerk logo"><span>SDA <em>Kerk</em></span></a><nav id="nav" class="site-nav" aria-label="${L('Hoofnavigasie','Main navigation')}">${nav}</nav><div class="header-actions"><select class="language" id="language" aria-label="Language"><option value="af">AF</option><option value="en">EN</option></select><a href="/gemeentes" class="button small">${L('Vind ’n gemeente','Find a church')} ↗</a><button class="nav-toggle" id="nav-toggle" aria-label="Menu" aria-expanded="false">☰</button></div></div></header><main id="main">${content}</main><footer class="footer"><div class="container"><div class="footer-cols"><div><a class="brand" href="/"><img src="/assets/sda-logo.png" alt=""><span>SDA Kerk</span></a><p>${L('’n Afrikaanse ruimte om die Bybel te ontdek, ons geloof beter te verstaan en ’n geloofsgemeenskap naby jou te vind.','An Afrikaans space to explore the Bible, understand our beliefs and find a faith community near you.')}</p>${socials()}</div><div><h4>${L('Ontdek','Explore')}</h4><div class="footer-links"><a href="/oor-ons">${L('Oor ons','About')}</a><a href="/bybel">${L('Die Bybel','The Bible')}</a><a href="/studie">${L('Bybelstudie','Bible study')}</a><a href="/boeke">${L('Boeke','Books')}</a></div></div><div><h4>${L('Verbind','Connect')}</h4><div class="footer-links"><a href="/videos">${L('Video’s','Videos')}</a><a href="/gemeentes">${L('Gemeentes','Churches')}</a><a href="/kontak">${L('Kontak ons','Contact us')}</a><a href="mailto:hi@sdakerk.com">hi@sdakerk.com</a></div></div><div><h4>${L('Inligting','Information')}</h4><div class="footer-links"><a href="/privaatheid">${L('Privaatheidsbeleid','Privacy policy')}</a><a href="/bepalings">${L('Gebruiksvoorwaardes','Terms of use')}</a><a href="https://adventist.org/en/beliefs" target="_blank" rel="noopener">${L('Ons geloofsoortuigings','Our beliefs')} ↗</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} SDA Kerk. ${L('Alle regte voorbehou.','All rights reserved.')}</span><span>${L('Geloof. Hoop. Gemeenskap.','Faith. Hope. Community.')}</span></div></div></footer><div id="cookie-slot"></div>`;$('#language').value=lang();$('#language').addEventListener('change',e=>{localStorage.setItem('sdakerk_lang',e.target.value);document.documentElement.lang=e.target.value;render()});$('#nav-toggle').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#nav-toggle').setAttribute('aria-expanded',String(open))};cookie()}
function header(kicker,title,desc){return `<section class="page-hero"><div class="container"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div></section>`}
function cookie(){if(localStorage.getItem('sdakerk_cookie'))return;$('#cookie-slot').innerHTML=`<div class="cookie" role="dialog" aria-label="${L('Koekies','Cookies')}"><p>${L('Ons gebruik plaaslike berging vir taal-, koekie- en boekmerkvoorkeure. Eksterne kaart-, lettertipe- en videodienste kan tegniese data ontvang wanneer hulle laai.','We use local storage for language, cookie and bookmark preferences. External map, font and video providers may receive technical data when loaded.')} <a href="/privaatheid"><u>${L('Meer inligting','Learn more')}</u></a>.</p><div class="cookie-actions"><button class="button ghost" id="cookie-essential">${L('Slegs noodsaaklik','Essential only')}</button><button class="button" id="cookie-accept">${L('Aanvaar','Accept')}</button></div></div>`;$('#cookie-accept').onclick=()=>{localStorage.setItem('sdakerk_cookie','accepted');$('#cookie-slot').innerHTML=''};$('#cookie-essential').onclick=()=>{localStorage.setItem('sdakerk_cookie','essential');$('#cookie-slot').innerHTML=''}}
function home(){layout(`<section class="hero"><div class="container hero-inner"><div><span class="eyebrow">${L('Welkom by SDA Kerk','Welcome to SDA Kerk')}</span><h1>${L('Geloof. Hoop. <span>’n Lewe met betekenis.</span>','Faith. Hope. <span>A life of purpose.</span>')}</h1><p class="hero-lead">${L('Ontdek ’n geloof wat in die Bybel gewortel is, op Jesus Christus gerig is en mense nader aan God en mekaar bring.','Discover a faith rooted in Scripture, centered on Jesus Christ, bringing people closer to God and one another.')}</p><div class="hero-actions"><a class="button light" href="/oor-ons">${L('Ontdek ons geloof','Explore our faith')} ↗</a><a class="button outline-white" href="/gemeentes">${L('Vind ’n gemeente','Find a church')} →</a></div></div><div class="hero-art"><div class="hero-arch"><img src="/assets/sda-logo.png" class="hero-logo" alt="Sewendedag-Adventistekerk"></div><div class="hero-floor"></div></div></div></section><section class="features-bar"><div class="container features-inner"><a href="/bybel" class="feature-short"><span class="symbol">✦</span><div><strong>${L('Ontdek die Skrif','Explore Scripture')}</strong><span>${L('Lees en vergelyk Bybelverse','Read and compare Bible verses')}</span></div></a><a href="/studie" class="feature-short"><span class="symbol">◉</span><div><strong>${L('Weeklikse Bybelstudie','Weekly Bible study')}</strong><span>${L('Groei elke dag in jou geloof','Grow in faith every day')}</span></div></a><a href="/gemeentes" class="feature-short"><span class="symbol">⌖</span><div><strong>${L('Vind jou gemeenskap','Find your community')}</strong><span>${L('Soek ’n gemeente naby jou','Find a nearby church')}</span></div></a></div></section><section class="section section-light"><div class="container split"><div><span class="eyebrow">${L('Wie ons is','Who we are')}</span><h2>${L('’n Geloof gebou op die Woord van God.','A faith built on the Word of God.')}</h2><p class="lead">${L('Sewendedag-Adventiste is Christene wat glo dat God elke mens liefhet en dat Jesus Christus die bron van verlossing, vrede en ware hoop is.','Seventh-day Adventists are Christians who believe God loves every person and that Jesus Christ is the source of salvation, peace and lasting hope.')}</p><p>${L('Ons aanbid God op die sewende dag, die Sabbat, en sien uit na die wederkoms van Jesus. Ons wil ons geloof daagliks uitleef deur diensbaarheid, gesonde lewe en omgee vir ons medemens.','We worship God on the seventh day, the Sabbath, and look forward to Jesus’ return. We seek to live our faith daily through service, healthy living and care for others.')}</p><a href="/oor-ons" class="text-link">${L('Leer ons beter ken','Get to know us')} →</a></div><div class="faith-art"><div class="ring"></div><div class="ring"></div><div class="ring"></div><div class="central"><img src="/assets/sda-logo.png" alt=""></div><span class="caption-bottom">${L('Geloof • Hoop • Liefde','Faith • Hope • Love')}</span></div></div></section><section class="section section-warm"><div class="container"><div class="section-head"><div><span class="eyebrow">${L('Begin jou ontdekking','Start your journey')}</span><h2>${L('’n Plek om te leer, lees en verbind.','A place to learn, read and connect.')}</h2></div><p class="muted">${L('Alles wat jy nodig het om meer oor die Bybel, ons geloof en ons gemeenskap te ontdek.','Everything you need to explore Scripture, our faith and our community.')}</p></div><div class="card-grid">${[[L('Die Bybel','The Bible'),L('Lees verse, vergelyk vertalings en bestudeer die Skrif in jou eie tyd.','Read verses, compare translations and study Scripture at your own pace.'),'/bybel','01','✳'],[L('Bybelstudie','Bible study'),L('Volg weeklikse Sabbatskoollesse en verdiep jou insig in God se Woord.','Follow weekly Sabbath School lessons and deepen your understanding of God’s Word.'),'/studie','02','◷'],[L('Vind ’n gemeente','Find a church'),L('Ontdek Afrikaanse Adventistegemeentes en maak kontak met mense naby jou.','Discover Afrikaans Adventist churches and connect with people near you.'),'/gemeentes','03','⌖']].map(([t,d,h,n,i])=>`<article class="info-card"><div class="icon-circle">${i}</div><div class="card-number">${n} / 03</div><h3>${t}</h3><p>${d}</p><a href="${h}" class="text-link">${L('Verken','Explore')} →</a></article>`).join('')}</div></div></section><section class="section section-light"><div class="container"><div class="cta-band"><div><span class="eyebrow" style="color:#e4c899">${L('Jy is welkom','You are welcome')}</span><h2>${L('Daar is ’n plek vir jou.','There is a place for you.')}</h2><p>${L('Of jy nou nuuskierig is of reeds deel is van ons geloofsfamilie.','Whether you are curious or already part of our faith family.')}</p></div><a class="button light" href="/gemeentes">${L('Soek ’n gemeente','Find a church')} ↗</a></div></div></section>`)}
const beliefGroups=[
{af:'God',en:'God',items:[['Die Heilige Skrif','Holy Scriptures','Die Ou en Nuwe Testament is deur God geïnspireer en die gesaghebbende grondslag van ons geloof.','The Old and New Testaments are inspired by God and the authoritative basis of our faith.'],['Die Drie-eenheid','The Trinity','Daar is een God: Vader, Seun en Heilige Gees.','There is one God: Father, Son and Holy Spirit.'],['God die Vader','God the Father','Die Vader is die Skepper, Onderhouer en Here van alles.','The Father is Creator, Sustainer and Sovereign of all.'],['God die Seun','God the Son','Jesus Christus het mens geword, vir ons gesterf, opgestaan en tree vir ons in.','Jesus Christ became human, died for us, rose again and intercedes for us.'],['God die Heilige Gees','God the Holy Spirit','Die Gees lei mense na Christus, oortuig van waarheid en rus gelowiges toe.','The Spirit leads people to Christ, convicts of truth and equips believers.']]},
{af:'Die mens',en:'Humanity',items:[['Die skepping','Creation','God het die hemel en aarde geskep en die sewende dag as rusdag geseën.','God created heaven and earth and blessed the seventh day as a day of rest.'],['Die aard van die mens','The nature of humanity','Mense is na God se beeld geskape en is vir lewe en afhanklikheid van Hom bedoel.','People were created in God’s image, meant to live in dependence on Him.']]},
{af:'Verlossing',en:'Salvation',items:[['Die groot stryd','The great controversy','Die Bybel beskryf ’n stryd tussen goed en kwaad, met Christus as oorwinnaar.','Scripture describes a struggle between good and evil, with Christ victorious.'],['Christus se lewe, dood en opstanding','Christ’s life, death and resurrection','Jesus se versoeningsdood en opstanding bied verlossing en nuwe lewe.','Jesus’ atoning death and resurrection offer salvation and new life.'],['Die ervaring van verlossing','The experience of salvation','Deur genade, deur geloof in Jesus, ontvang ons vergifnis en herstel.','By grace, through faith in Jesus, we receive forgiveness and restoration.'],['Groei in Christus','Growing in Christ','Ons groei deur gebed, Bybelstudie, aanbidding en diens aan ander.','We grow through prayer, Bible study, worship and serving others.']]},
{af:'Die kerk',en:'The church',items:[['Die kerk','The church','Die kerk is die gemeenskap van gelowiges wat Christus as Here bely.','The church is the community of believers who confess Christ as Lord.'],['Die oorblyfsel en sy sending','The remnant and its mission','Die kerk word geroep om God se boodskap van hoop aan die wêreld te verkondig.','The church is called to share God’s message of hope with the world.'],['Eenheid in die liggaam van Christus','Unity in the body of Christ','Gelowiges is een in Christus, oor taal en kultuurgrense heen.','Believers are one in Christ across language and culture.'],['Die doop','Baptism','Die gelowige se doop deur onderdompeling getuig van geloof en ’n nuwe lewe.','Believer’s baptism by immersion expresses faith and new life.'],['Die nagmaal','The Lord’s Supper','Ons gedenk Christus se offer deur die nagmaal en diens van nederigheid.','We remember Christ’s sacrifice through Communion and humble service.']]},
{af:'Die Christelike lewe',en:'Christian living',items:[['Geestelike gawes en bedieninge','Spiritual gifts and ministries','Die Heilige Gees gee gawes om die kerk en ons medemens te dien.','The Holy Spirit gives gifts to serve the church and others.'],['Die gawe van profesie','The gift of prophecy','Ons erken die profetiese gawe en toets alle lering aan die Bybel.','We recognize the prophetic gift and test all teaching against Scripture.'],['God se wet','The law of God','Die Tien Gebooie wys ons op God se karakter en Sy wil vir ons lewens.','The Ten Commandments reveal God’s character and His will for our lives.'],['Die Sabbat','The Sabbath','Die sewende dag, Saterdag, is ’n tyd vir rus, aanbidding en gemeenskap.','The seventh day, Saturday, is for rest, worship and community.'],['Rentmeesterskap','Stewardship','Ons sorg verantwoordelik vir tyd, gawes, besittings en die skepping.','We care responsibly for time, gifts, possessions and creation.'],['Christelike lewenswyse','Christian behavior','Ons strewe na gesonde, verantwoordelike en liefdevolle keuses.','We seek healthy, responsible and loving choices.'],['Die huwelik en gesin','Marriage and the family','Die huwelik en gesin is plekke waar liefde, trou en sorg gekweek word.','Marriage and family foster love, faithfulness and care.']]},
{af:'Herstel en die toekoms',en:'Restoration and the future',items:[['Christus se bediening in die hemelse heiligdom','Christ’s ministry in the heavenly sanctuary','Ons glo Christus dien as ons Hoëpriester en dat God regverdig oordeel.','We believe Christ ministers as our High Priest and that God judges justly.'],['Die wederkoms van Christus','The second coming of Christ','Jesus sal persoonlik, sigbaar en in heerlikheid terugkeer.','Jesus will return personally, visibly and in glory.'],['Die dood en opstanding','Death and resurrection','Die dood is ’n onbewuste rus tot die opstanding wanneer Christus kom.','Death is an unconscious rest until the resurrection at Christ’s return.'],['Die millennium en die einde van sonde','The millennium and the end of sin','God sal sonde en kwaad finaal beëindig.','God will ultimately bring sin and evil to an end.'],['Die nuwe aarde','The new earth','God sal ’n nuwe hemel en nuwe aarde sonder lyding en dood skep.','God will create a new heaven and new earth without suffering or death.']]}];
function about(){layout(header(L('Ons identiteit','Our identity'),L('Oor die Sewendedag-Adventistekerk','About the Seventh-day Adventist Church'),L('Ons is ’n wêreldwye Christelike geloofsgemeenskap wat die Bybel bestudeer, Jesus volg en hoop vir die toekoms verkondig.','We are a worldwide Christian community that studies the Bible, follows Jesus and shares hope for the future.'))+`<section class="section section-light"><div class="container split"><div><span class="eyebrow">${L('Ons roeping','Our calling')}</span><h2>${L('Jesus in die middelpunt van alles.','Jesus at the center of everything.')}</h2><p>${L('Die Sewendedag-Adventistekerk het in die negentiende eeu uit ’n beweging van Bybelstudie en verwagting van Christus se wederkoms ontstaan. Vandag is dit ’n internasionale Christelike kerk wat mense uit baie tale, kulture en agtergronde verenig.','The Seventh-day Adventist Church grew from a nineteenth-century movement of Bible study and expectation of Christ’s return. Today it is an international Christian church uniting people from many languages, cultures and backgrounds.')}</p><p>${L('Die naam verwys na twee kenmerke: die sewende dag as die Bybelse Sabbat en die advent, of wederkoms, van Jesus Christus. Adventiste beklemtoon die gesag van die Bybel, redding deur genade, gesonde lewenskeuses en liefdevolle diens.','The name reflects two convictions: the seventh day as the biblical Sabbath and the advent, or return, of Jesus Christ. Adventists emphasize biblical authority, salvation by grace, healthy living and compassionate service.')}</p></div><div class="faith-art"><div class="ring"></div><div class="ring"></div><div class="ring"></div><div class="central"><img src="/assets/sda-logo.png" alt=""></div></div></div></section><section class="section section-warm"><div class="container"><span class="eyebrow">${L('Waarin ons glo','What we believe')}</span><h2>${L('Ons 28 geloofsoortuigings.','Our 28 fundamental beliefs.')}</h2><p class="lead narrow">${L('Ons aanvaarding van die Bybel as die hoogste gesag vorm die grondslag van 28 geloofsoortuigings, hier kortliks in ses temas saamgevat.','The Bible as our highest authority underpins 28 fundamental beliefs, summarized below in six themes.')}</p><div style="margin-top:33px">${beliefGroups.map((g,i)=>`<article class="belief-group"><div class="belief-top"><b>${String(i+1).padStart(2,'0')}</b><h2>${L(g.af,g.en)}</h2></div><div class="belief-list">${g.items.map(([af,en,da,de],j)=>`<div class="belief-item"><strong>${i===0?j+1:beliefGroups.slice(0,i).reduce((n,x)=>n+x.items.length,0)+j+1}. ${L(af,en)}</strong><p>${L(da,de)}</p></div>`).join('')}</div></article>`).join('')}</div><div class="aside-note">${L('Hierdie is ’n toeganklike opsomming, nie die volledige amptelike formulering nie. Lees die volledige 28 geloofsoortuigings by','This is an accessible summary, not the full official wording. Read all 28 beliefs at')} <a href="https://adventist.org/en/beliefs" target="_blank" rel="noopener"><u>adventist.org</u> ↗</a>.</div></div></section>`)}
