function filterBooks(){const q=$('#book-search').value.toLowerCase().trim(),language=$('#book-language').value,fav=favorites();let arr=egwBooks.filter(b=>(language!=='af'||officialAfrikaansCodes.has(b[3]))&&(bookCategory==='Almal'||b[2]===bookCategory)&&(!onlyFav||fav.includes(b[3]))&&[b[0],b[1],b[2],b[3]].join(' ').toLowerCase().includes(q));if($('#book-sort').value==='az')arr.sort((a,b)=>a[language==='af'?1:0].localeCompare(b[language==='af'?1:0]));else arr.sort((a,b)=>b[4]-a[4]);$('#book-count').textContent=`${arr.length} ${L('boeke in die gids','books in the guide')}`;$('#book-grid').innerHTML=arr.map((b)=>{const i=egwBooks.indexOf(b),saved=fav.includes(b[3]),name=language==='af'?b[1]:b[0];return `<article class="book-card"><a href="${bookSource(b,language)}" target="_blank" rel="noopener" title="${L('Soek in EGW Writings','Search EGW Writings')}"><div class="book-cover" style="background:${colors[i%colors.length]}"><span class="cover-symbol">✣</span><div class="cover-title">${esc(name)}</div><span class="cover-author">Ellen G. White</span></div></a><div class="book-content"><h3>${esc(name)}</h3><p>${esc(b[2])} ${b[4]?' • ★':''}</p><div class="book-actions"><a class="text-link" style="font-size:.75rem" href="${bookSource(b,language)}" target="_blank" rel="noopener">${L('Soek en lees','Find and read')} ↗</a><button class="heart ${saved?'saved':''}" data-fav="${esc(b[3])}" aria-label="${L('Wissel gunsteling','Toggle favourite')}">${saved?'♥':'♡'}</button></div></div></article>`}).join('')||`<div class="empty">${L('Geen boeke pas by jou soektog nie.','No books match your search.')}</div>`;$$('[data-fav]').forEach(el=>el.onclick=()=>{let a=favorites();a=a.includes(el.dataset.fav)?a.filter(x=>x!==el.dataset.fav):[...a,el.dataset.fav];localStorage.setItem('sdakerk_fav_books',JSON.stringify(a));filterBooks()})}
